# Writes the hedra command files of Cloud Putt's props: ball.txt, flag.txt, gate.txt (the sliding
# block), post.txt (a bumper), puff.txt (a cloud puff), tree.txt (a lollipop tree), drop.txt (a
# splash droplet), spark.txt (confetti), ripple.txt (a splash ring). Run from models/env:
#   /usr/bin/python3 make_env.py
# Up Z, front -Y (hedra); colours exact Taffy 16. World (glTF) = (x, z, -y) of hedra.
HEX = {"white": "fafffc", "ice": "a3c0e6", "peri": "6275ba", "peach": "ffab7b", "pink": "ff6c7a",
       "rose": "dc435b", "wine": "a63d57", "orange": "f58931", "red": "db4b3d", "yellow": "ffeb33",
       "blue": "448de7"}


def col(n):
    h = HEX[n]
    r, g, b = (int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
    return f"--base-color {r:.4f} {g:.4f} {b:.4f}"


files = {}

files["ball"] = f"""# Ball: a faceted white ball r 0.16 m with a pink band round its equator (so its roll reads).
# Origin at its centre. Generated by make_env.py.
new
material new Ball {col('white')} --no-slot
material new Band {col('pink')} --no-slot
add mesh ico-sphere --name Ball --subdivisions 2 --radius 0.16 --location 0 0 0
material assign Ball
mode edit
select face where "abs(pos.x) < 0.045"
material assign Band
mode object
shade flat
export ball.glb
"""

files["flag"] = f"""# Flag: a white pole 1.35 m tall standing in the cup, a red knob on top and a yellow pennant
# 0.6 m long (tapering to a point) near the top, pointing right. Origin at the pole's foot.
new
material new Pole {col('white')} --no-slot
material new Knob {col('red')} --no-slot
material new Pennant {col('yellow')} --no-slot
add mesh cylinder --name Pole --vertices 6 --radius 0.04 --depth 1.35 --location 0 0 0.675
material assign Pole
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
add mesh ico-sphere --name Knob --subdivisions 1 --radius 0.07 --location 0 0 1.39
material assign Knob
add mesh cube --name Pennant --size 1 --location 0 0 0
scale 0.62 0.05 0.42
apply --scale
translate 0.33 0 1.1
apply --location
mode edit
select vert where "pos.x > 0.6"
scale 1 1 0.12
mode object
material assign Pennant
select all
shade flat
export flag.glb
"""

files["gate"] = f"""# Sliding gate: a candy block 0.5 m (along x) by 1.1 m (along the lane's width) by 0.45 m tall,
# a white top. Origin at the centre of its foot. Generated by make_env.py.
new
material new Gate {col('pink')} --no-slot
material new Top {col('white')} --no-slot
add mesh cube --name Gate --size 1 --location 0 0 0.225
scale 0.5 1.1 0.45
apply --scale
material assign Gate
mode edit
select face where "normal.z > 0.9"
material assign Top
select face where "normal.z < -0.9"
delete only-faces
mode object
shade flat
export gate.glb
"""

bands = []
for i in range(4):
    z0 = 0.125 * i
    bands.append(f"add mesh cylinder --name P{i} --vertices 10 --radius 0.3 --depth 0.125 --location 0 0 {z0 + 0.0625:.4f}")
    bands.append(f"material assign {'Post' if i % 2 == 0 else 'Stripe'}")
    bands.append("mode edit")
    bands.append('select face where "normal.z > 0.9 || normal.z < -0.9"' if i < 3 else 'select face where "normal.z < -0.9"')
    bands.append("delete only-faces")
    bands.append("mode object")
files["post"] = f"""# Bumper post: a ten-sided candy-striped post r 0.3 m, 0.5 m tall (pink and white bands of
# 0.125 m), a yellow cap. Origin at the centre of its foot. Generated by make_env.py.
new
material new Post {col('pink')} --no-slot
material new Stripe {col('white')} --no-slot
material new Cap {col('yellow')} --no-slot
""" + "\n".join(bands) + f"""
select P3
active P3
mode edit
select face where "normal.z > 0.9"
material assign Cap
mode object
select P0 P1 P2 P3
active P0
join
rename P0 Post
shade flat
export post.glb
"""

files["puff"] = f"""# Cloud puff: a faceted ball of cloud r 1 m (scaled per instance), white with its underside in
# ice blue; the faces pointing straight down deleted (never seen). Origin at its centre.
new
material new Cloud {col('white')} --no-slot
material new Under {col('ice')} --no-slot
add mesh ico-sphere --name Puff --subdivisions 2 --radius 1.0 --location 0 0 0
material assign Cloud
mode edit
select face where "pos.z < -0.35"
material assign Under
select face where "normal.z < -0.8"
delete only-faces
mode object
shade flat
export puff.glb
"""

files["tree"] = f"""# Lollipop tree: a wine trunk 0.9 m and a pink faceted crown r 0.6 m. Origin at the trunk's foot.
new
material new Trunk {col('wine')} --no-slot
material new Crown {col('pink')} --no-slot
add mesh cylinder --name Trunk --vertices 6 --radius 0.09 --depth 0.95 --location 0 0 0.47
material assign Trunk
mode edit
select face where "abs(normal.z) > 0.9"
delete only-faces
mode object
add mesh ico-sphere --name Crown --subdivisions 1 --radius 0.62 --location 0 0 1.35
material assign Crown
select all
shade flat
export tree.glb
"""

files["drop"] = f"""# Splash droplet: a tiny white icosahedron r 0.07 m. Origin at its centre.
new
material new Drop {col('white')} --no-slot
add mesh ico-sphere --name Drop --subdivisions 1 --radius 0.07 --location 0 0 0
material assign Drop
shade flat
export drop.glb
"""

files["spark"] = f"""# Confetti spark: a tiny yellow icosahedron r 0.07 m. Origin at its centre.
new
material new Spark {col('yellow')} --no-slot
add mesh ico-sphere --name Spark --subdivisions 1 --radius 0.07 --location 0 0 0
material assign Spark
shade flat
export spark.glb
"""

files["ripple"] = f"""# Splash ring: a flat white ring 0.7 m across (baked at its largest, scaled down by the game).
# Origin at its centre.
new
material new Ring {col('white')} --no-slot
add mesh torus --name Ring --major-segments 16 --minor-segments 4 --major-radius 0.35 --minor-radius 0.05 --location 0 0 0
scale 1 1 0.4
apply --scale
material assign Ring
shade flat
export ripple.glb
"""

for k, v in files.items():
    open(f"{k}.txt", "w").write(v)
print("wrote", ", ".join(f"{k}.txt" for k in files))
